alter table loans add column if not exists loan_amount numeric(14,2);
create table if not exists monthly_funding_goals (id uuid primary key, year smallint not null, month smallint not null check (month between 1 and 12), funded_loan_goal integer not null check (funded_loan_goal>0), funded_volume_goal numeric(14,2) not null check (funded_volume_goal>0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(year,month));
insert into monthly_funding_goals (id,year,month,funded_loan_goal,funded_volume_goal) values ('00000000-0000-4000-8000-000000000009',2026,9,30,15000000) on conflict(year,month) do nothing;
update loans l set loan_amount=(select nullif(payload->>'loanAmount','')::numeric from inbound_events i where i.source='zapier-arive' and i.idempotency_key=e.source_event_id and nullif(i.payload->>'loanAmount','') is not null order by i.received_at desc limit 1) from loan_stage_events e where e.loan_id=l.id and l.loan_amount is null;
create or replace function hfn_persist_safe_loan_amount() returns trigger language plpgsql as $$ begin update loans set loan_amount=coalesce(loan_amount,(select nullif(payload->>'loanAmount','')::numeric from inbound_events where source='zapier-arive' and idempotency_key=new.source_event_id and nullif(payload->>'loanAmount','') is not null order by received_at desc limit 1)) where id=new.loan_id; return new; end; $$;
create trigger hfn_persist_safe_loan_amount_on_event after insert on loan_stage_events for each row execute function hfn_persist_safe_loan_amount();
